<?php require_once __DIR__.'/includes/bootstrap.php'; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$phone=trim($_POST['phone']??'');$role=$_POST['role']??'buyer';$pass=$_POST['password']??'';if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<10||!in_array($role,['farmer','buyer'],true)){flash('error','Enter valid details. Password must be at least 10 characters; choose farmer or buyer.');}else{try{$st=$pdo->prepare('INSERT INTO users(name,email,phone,password_hash,role) VALUES(?,?,?,?,?)');$st->execute([$name,$email,$phone,password_hash($pass,PASSWORD_DEFAULT),$role]);flash('success','Account created. You can now log in.');redirect('login.php');}catch(PDOException $e){flash('error','That email may already be registered.');}}}include __DIR__.'/includes/header.php'; ?>
<section class="auth-wrap"><form class="panel auth-panel" method="post"><span class="eyebrow">GET STARTED</span><h1>Create your account</h1><?= csrf_field() ?><?= show_flash() ?><label>Full name</label><input name="name" required maxlength="100" autocomplete="name"><label>Email address</label><input type="email" name="email" required maxlength="190" autocomplete="email"><label>Phone (optional)</label><input name="phone" maxlength="30"><label>Account type</label><select name="role"><option value="buyer">Buyer</option><option value="farmer">Farmer</option></select><label>Password (minimum 10 characters)</label><input type="password" name="password" required minlength="10" autocomplete="new-password"><button class="btn" type="submit">Create account</button><p>Already registered? <a href="login.php">Log in</a></p></form></section><?php include __DIR__.'/includes/footer.php'; ?>